class Solution:
    def maxSumOfThree(self, nums: List[int]) -> int:
        b = [[], [], []]
        for x in nums: b[x % 3].append(x)
        for lst in b: lst.sort(reverse=True)
        cands = []
        for r in range(3):
            if len(b[r]) >= 3: cands.append(sum(b[r][:3]))
        if b[0] and b[1] and b[2]:
            cands.append(b[0][0] + b[1][0] + b[2][0])
        return max(cands) if cands else 0

