class Solution {
public:
    int maxSumOfThree(vector<int>& nums) {
        vector<int> b[3];
        for (int x : nums) b[x % 3].push_back(x);
        for (auto& v : b) sort(v.rbegin(), v.rend());
        int best = 0; bool any = false;
        auto consider = [&](long long s) { any = true; best = max(best, (int)s); };
        for (int r = 0; r < 3; r++)
            if (b[r].size() >= 3) consider((long long)b[r][0] + b[r][1] + b[r][2]);
        if (!b[0].empty() && !b[1].empty() && !b[2].empty())
            consider((long long)b[0][0] + b[1][0] + b[2][0]);
        return any ? best : 0;
    }
};

