class Solution {
    public int maxSumOfThree(int[] nums) {
        List<List<Integer>> b = new ArrayList<>();
        for (int i = 0; i < 3; i++) b.add(new ArrayList<>());
        for (int x : nums) b.get(x % 3).add(x);
        for (List<Integer> l : b) Collections.sort(l, Collections.reverseOrder());
        int best = 0; boolean any = false;
        for (int r = 0; r < 3; r++)
            if (b.get(r).size() >= 3) {
                int s = b.get(r).get(0) + b.get(r).get(1) + b.get(r).get(2);
                best = Math.max(best, s); any = true;
            }
        if (!b.get(0).isEmpty() && !b.get(1).isEmpty() && !b.get(2).isEmpty()) {
            int s = b.get(0).get(0) + b.get(1).get(0) + b.get(2).get(0);
            best = Math.max(best, s); any = true;
        }
        return any ? best : 0;
    }
}

