        tops = [[] for _ in range(3)]
        for x in nums:
            r = x % 3
            tops[r].append(x)
            tops[r].sort(reverse=True)
            del tops[r][3:]
        cands = []
        for r in range(3):
            if len(tops[r]) == 3: cands.append(sum(tops[r]))
        if all(tops[r] for r in range(3)):
            cands.append(tops[0][0] + tops[1][0] + tops[2][0])
        return max(cands) if cands else 0

