class Solution {
    public int maxSumOfThree(int[] nums) {
        List<List<Integer>> tops = new ArrayList<>();
        for (int i = 0; i < 3; i++) tops.add(new ArrayList<>());
        for (int x : nums) {
            List<Integer> t = tops.get(x % 3);
            t.add(x);
            Collections.sort(t, Collections.reverseOrder());
            while (t.size() > 3) t.remove(3);
        }
        int best = 0; boolean any = false;
        for (int r = 0; r < 3; r++)
            if (tops.get(r).size() == 3) {
                best = Math.max(best, tops.get(r).get(0) + tops.get(r).get(1) + tops.get(r).get(2));
                any = true;
            }
        if (!tops.get(0).isEmpty() && !tops.get(1).isEmpty() && !tops.get(2).isEmpty()) {
            best = Math.max(best, tops.get(0).get(0) + tops.get(1).get(0) + tops.get(2).get(0));
            any = true;
        }
        return any ? best : 0;
    }
}

